typescript.code:
export function palindromePairs(words: string[]): number[][] {
  const isPal = (s: string) => s === [...s].reverse().join('');
  const index = new Map(words.map((word, i) => [word, i]));
  const out: number[][] = [];
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i];
    for (let cut = 0; cut <= word.length; cut += 1) {
      const left = word.slice(0, cut), right = word.slice(cut);
      const revRight = [...right].reverse().join(''), revLeft = [...left].reverse().join('');
      if (isPal(left) && index.has(revRight) && index.get(revRight) !== i) out.push([index.get(revRight)!, i]);
      if (cut !== word.length && isPal(right) && index.has(revLeft) && index.get(revLeft) !== i) out.push([i, index.get(revLeft)!]);
    }
  }
  return out;
}

