class Node:
    def __init__(self):
        self.children = {}
        self.content = None

class FileSystem:
    def __init__(self):
        self.root = Node()
    def _walk(self, path):
        node = self.root
        for part in filter(None, path.split('/')):
            node = node.children.setdefault(part, Node())
        return node
    def ls(self, path):
        node = self._walk(path)
        if node.content is not None:
            return [path.split('/')[-1]]
        return sorted(node.children)
    def mkdir(self, path):
        self._walk(path)
    def add_content(self, path, content):
        node = self._walk(path)
        node.content = (node.content or '') + content
    def read_content(self, path):
        return self._walk(path).content or ''

