export class FileSystem {
  private root = new FsNode();
  private walk(path: string): FsNode {
    let node = this.root;
    for (const part of path.split('/').filter(Boolean)) {
      if (!node.children.has(part)) node.children.set(part, new FsNode());
      node = node.children.get(part)!;
    }
    return node;
  }
  ls(path: string): string[] { const node = this.walk(path); return node.content === undefined ? [...node.children.keys()].sort() : [path.split('/').pop()!]; }
  mkdir(path: string): void { this.walk(path); }
  addContent(path: string, content: string): void { const node = this.walk(path); node.content = (node.content ?? '') + content; }
  readContent(path: string): string { return this.walk(path).content ?? ''; }
}

