class FileSystem {
  static class Node { Map<String, Node> children = new TreeMap<>(); StringBuilder content; }
  private final Node root = new Node();
  private Node walk(String path) {
    Node node = root;
    for (String part : path.split("/")) if (!part.isEmpty()) node = node.children.computeIfAbsent(part, k -> new Node());
    return node;
  }
  List<String> ls(String path) { Node node = walk(path); return node.content != null ? List.of(path.substring(path.lastIndexOf('/') + 1)) : new ArrayList<>(node.children.keySet()); }
  void mkdir(String path) { walk(path); }
  void addContent(String path, String content) { Node node = walk(path); if (node.content == null) node.content = new StringBuilder(); node.content.append(content); }
  String readContent(String path) { Node node = walk(path); return node.content == null ? "" : node.content.toString(); }
}

