export class FileSystemMap {
  private dirs = new Map<string, Set<string>>([['/', new Set()]]);
  private files = new Map<string, string>();
  mkdir(path: string): void {
    let cur = '';
    for (const part of path.split('/').filter(Boolean)) {
      const parent = cur || '/';
      cur = cur ? cur + '/' + part : '/' + part;
      if (!this.dirs.has(parent)) this.dirs.set(parent, new Set());
      this.dirs.get(parent)!.add(part);
      if (!this.dirs.has(cur)) this.dirs.set(cur, new Set());
    }
  }
  addContent(path: string, content: string): void { const slash = path.lastIndexOf('/'); const dir = path.slice(0, slash) || '/'; const name = path.slice(slash + 1); this.mkdir(dir); this.dirs.get(dir)!.add(name); this.files.set(path, (this.files.get(path) ?? '') + content); }
  ls(path: string): string[] { return this.files.has(path) ? [path.slice(path.lastIndexOf('/') + 1)] : [...(this.dirs.get(path) ?? [])].sort(); }
}

