class FileSystemMap {
  private final Map<String, TreeSet<String>> dirs = new HashMap<>();
  private final Map<String, StringBuilder> files = new HashMap<>();
  FileSystemMap() { dirs.put("/", new TreeSet<>()); }
  void mkdir(String path) {
    String cur = "";
    for (String part : path.split("/")) if (!part.isEmpty()) { String parent = cur.isEmpty() ? "/" : cur; cur = cur.isEmpty() ? "/" + part : cur + "/" + part; dirs.computeIfAbsent(parent, k -> new TreeSet<>()).add(part); dirs.computeIfAbsent(cur, k -> new TreeSet<>()); }
  }
  void addContent(String path, String content) { int slash = path.lastIndexOf('/'); String dir = slash == 0 ? "/" : path.substring(0, slash); String name = path.substring(slash + 1); mkdir(dir); dirs.get(dir).add(name); files.computeIfAbsent(path, k -> new StringBuilder()).append(content); }
  List<String> ls(String path) { return files.containsKey(path) ? List.of(path.substring(path.lastIndexOf('/') + 1)) : new ArrayList<>(dirs.getOrDefault(path, new TreeSet<>())); }
}

