def alien_order_dfs(words):
    graph = {ch: set() for word in words for ch in word}
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return ''
        for x, y in zip(a, b):
            if x != y:
                graph[x].add(y)
                break
    color = {}
    out = []
    def dfs(ch):
        if color.get(ch) == 1:
            return False
        if color.get(ch) == 2:
            return True
        color[ch] = 1
        for nxt in graph[ch]:
            if not dfs(nxt):
                return False
        color[ch] = 2
        out.append(ch)
        return True
    return ''.join(reversed(out)) if all(dfs(ch) for ch in graph) else ''

