String alienOrderDfs(String[] words) {
  Map<Character, Set<Character>> graph = new HashMap<>();
  for (String word : words) for (char ch : word.toCharArray()) graph.putIfAbsent(ch, new HashSet<>());
  for (int i = 0; i + 1 < words.length; i++) {
    String a = words[i], b = words[i + 1];
    if (a.length() > b.length() && a.startsWith(b)) return "";
    for (int j = 0; j < Math.min(a.length(), b.length()); j++) if (a.charAt(j) != b.charAt(j)) { graph.get(a.charAt(j)).add(b.charAt(j)); break; }
  }
  Map<Character, Integer> color = new HashMap<>();
  StringBuilder out = new StringBuilder();
  for (char ch : graph.keySet()) if (!alienDfs(ch, graph, color, out)) return "";
  return out.reverse().toString();
}
boolean alienDfs(char ch, Map<Character, Set<Character>> graph, Map<Character, Integer> color, StringBuilder out) {
  if (color.getOrDefault(ch, 0) == 1) return false;
  if (color.getOrDefault(ch, 0) == 2) return true;
  color.put(ch, 1);
  for (char next : graph.get(ch)) if (!alienDfs(next, graph, color, out)) return false;
  color.put(ch, 2);
  out.append(ch);
  return true;
}

