export function twoSumSorted(nums: number[], target: number): number[] {
  const pairs = nums.map((value, index) => ({ value, index })).sort((a, b) => a.value - b.value);
  let left = 0;
  let right = pairs.length - 1;
  while (left < right) {
    const total = pairs[left].value + pairs[right].value;
    if (total === target) return [pairs[left].index, pairs[right].index];
    if (total < target) left += 1;
    else right -= 1;
  }
  return [];
}

