export class LRUCacheSimple {
  private clock = 0;
  private data = new Map<number, { value: number; used: number }>();
  constructor(private capacity: number) {}
  get(key: number): number {
    const item = this.data.get(key);
    if (!item) return -1;
    item.used = ++this.clock;
    return item.value;
  }
  put(key: number, value: number): void {
    this.data.set(key, { value, used: ++this.clock });
    if (this.data.size <= this.capacity) return;
    let oldestKey = key;
    let oldest = Infinity;
    for (const [k, item] of this.data) if (item.used < oldest) { oldest = item.used; oldestKey = k; }
    this.data.delete(oldestKey);
  }
}

