def find_median_sorted_arrays(a, b):
    if len(a) > len(b):
        a, b = b, a
    total = len(a) + len(b)
    half = (total + 1) // 2
    lo, hi = 0, len(a)
    while lo <= hi:
        i = (lo + hi) // 2
        j = half - i
        a_left = float('-inf') if i == 0 else a[i - 1]
        a_right = float('inf') if i == len(a) else a[i]
        b_left = float('-inf') if j == 0 else b[j - 1]
        b_right = float('inf') if j == len(b) else b[j]
        if a_left <= b_right and b_left <= a_right:
            if total % 2:
                return max(a_left, b_left)
            return (max(a_left, b_left) + min(a_right, b_right)) / 2
        if a_left > b_right:
            hi = i - 1
        else:
            lo = i + 1

