export function medianSortedArrays(a: number[], b: number[]): number {
  if (a.length > b.length) return medianSortedArrays(b, a);
  const total = a.length + b.length;
  const half = Math.floor((total + 1) / 2);
  let lo = 0, hi = a.length;
  while (lo <= hi) {
    const i = Math.floor((lo + hi) / 2);
    const j = half - i;
    const aLeft = i === 0 ? -Infinity : a[i - 1];
    const aRight = i === a.length ? Infinity : a[i];
    const bLeft = j === 0 ? -Infinity : b[j - 1];
    const bRight = j === b.length ? Infinity : b[j];
    if (aLeft <= bRight && bLeft <= aRight) return total % 2 ? Math.max(aLeft, bLeft) : (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
    if (aLeft > bRight) hi = i - 1; else lo = i + 1;
  }
  return 0;
}

