export function cleanParentheses(s: string): string {
  const stack: number[] = [];
  const remove = new Set<number>();
  for (let i = 0; i < s.length; i += 1) {
    if (s[i] === '(') stack.push(i);
    else if (s[i] === ')') {
      if (stack.length) stack.pop();
      else remove.add(i);
    }
  }
  for (const i of stack) remove.add(i);
  return [...s].filter((_, i) => !remove.has(i)).join('');
}

