String cleanParentheses(String s) {
  Deque<Integer> stack = new ArrayDeque<>();
  Set<Integer> remove = new HashSet<>();
  for (int i = 0; i < s.length(); i++) {
    char ch = s.charAt(i);
    if (ch == '(') stack.push(i);
    else if (ch == ')') {
      if (!stack.isEmpty()) stack.pop();
      else remove.add(i);
    }
  }
  remove.addAll(stack);
  StringBuilder out = new StringBuilder();
  for (int i = 0; i < s.length(); i++) if (!remove.contains(i)) out.append(s.charAt(i));
  return out.toString();
}

