class MinStackEncoded {
  private final Deque<Long> stack = new ArrayDeque<>();
  private long minValue = 0;
  void push(int value) {
    if (stack.isEmpty()) { stack.push(0L); minValue = value; return; }
    long delta = value - minValue;
    stack.push(delta);
    if (delta < 0) minValue = value;
  }
  int pop() {
    long delta = stack.pop();
    long value = delta < 0 ? minValue : minValue + delta;
    if (delta < 0) minValue -= delta;
    return (int) value;
  }
  int getMin() { return (int) minValue; }
}

