def longest_valid_dp(s):
    dp = [0] * len(s)
    best = 0
    for i, ch in enumerate(s):
        if ch == ')':
            match = i - dp[i - 1] - 1
            if match >= 0 and s[match] == '(':
                dp[i] = dp[i - 1] + 2 + (dp[match - 1] if match > 0 else 0)
                best = max(best, dp[i])
    return best

