  int best = 0;
  for (int i = 0; i < s.length(); i++) {
    if (s.charAt(i) != ')') continue;
    int match = i - (i > 0 ? dp[i - 1] : 0) - 1;
    if (match >= 0 && s.charAt(match) == '(') {
      dp[i] = (i > 0 ? dp[i - 1] : 0) + 2 + (match > 0 ? dp[match - 1] : 0);
      best = Math.max(best, dp[i]);
    }
  }
  return best;
}

