import heapq

class ExpiringCacheHeap:
    def __init__(self):
        self.data = {}
        self.heap = []

    def set(self, key, value, ttl, now):
        expires = now + ttl
        self.data[key] = (value, expires)
        heapq.heappush(self.heap, (expires, key))

    def cleanup(self, now):
        while self.heap and self.heap[0][0] <= now:
            expires, key = heapq.heappop(self.heap)
            if self.data.get(key, (None, None))[1] == expires:
                del self.data[key]

typescript.code:
export class ExpiringCacheHeap<V> {
  private data = new Map<string, { value: V; expiresAt: number }>();
  private heap: Array<[number, string]> = [];
  set(key: string, value: V, ttl: number, now: number): void {
    const expiresAt = now + ttl;
    this.data.set(key, { value, expiresAt });
    this.heap.push([expiresAt, key]);
    this.heap.sort((a, b) => a[0] - b[0]);
  }
  cleanup(now: number): void {
    while (this.heap.length && this.heap[0][0] <= now) {
      const [expiresAt, key] = this.heap.shift()!;
      if (this.data.get(key)?.expiresAt === expiresAt) this.data.delete(key);
    }
  }
}

java.code:
class ExpiringCacheHeap<V> {
  record Entry<V>(V value, long expiresAt) {}
  private final Map<String, Entry<V>> data = new HashMap<>();
  private final PriorityQueue<Object[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> (Long) a[0]));
  void set(String key, V value, long ttl, long now) {
    long expires = now + ttl;
    data.put(key, new Entry<>(value, expires));
    heap.add(new Object[] { expires, key });
  }
  void cleanup(long now) {
    while (!heap.isEmpty() && (Long) heap.peek()[0] <= now) {
      Object[] item = heap.remove();
      Entry<V> current = data.get((String) item[1]);
      if (current != null && current.expiresAt() == (Long) item[0]) data.remove((String) item[1]);
    }
  }
}

