export function shortestPath(graph: Map<string, Array<[string, number]>>, start: string, target: string): number {
  const dist = new Map<string, number>([[start, 0]]);
  const heap: Array<[number, string]> = [[0, start]];
  while (heap.length) {
    heap.sort((a, b) => a[0] - b[0]);
    const [cost, node] = heap.shift()!;
    if (node === target) return cost;
    if (cost !== dist.get(node)) continue;
    for (const [next, weight] of graph.get(node) ?? []) {
      const newCost = cost + weight;
      if (newCost < (dist.get(next) ?? Infinity)) { dist.set(next, newCost); heap.push([newCost, next]); }
    }
  }
  return -1;
}

