export function minMeetingRooms(intervals: number[][]): number {
  intervals.sort((a, b) => a[0] - b[0]);
  const ends: number[] = [];
  let best = 0;
  for (const [start, end] of intervals) {
    ends.sort((a, b) => a - b);
    if (ends.length && ends[0] <= start) ends.shift();
    ends.push(end);
    best = Math.max(best, ends.length);
  }
  return best;
}

